// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(address player, uint256 amount) public {
        vm.assume(player != address(0) && player != address(this));
        vm.deal(player, amount);
        // Open to public
        c.OpenToThePublic();
        // Player wagers
        vm.prank(player, player);
        c.wager{value: 0}();
        // After AdjustBetAmounts, the reference sets wager[player] to 0
        c.AdjustBetAmounts(amount);
        // In reference: wager[player] should be 0
        assertTrue(c.hasPlayerWagered(player) == false);
    }
}

